import { useEffect, useState } from 'react'
import type { AnalysisResult } from './api'
import type { Lang } from './i18n'

// Public demo of the hosted build, usable without an account: a pre-computed
// analysis of the sample capture (generated by scripts/make-demo-data.py) that
// the dashboard renders as-is. No backend and no login are involved, and the
// self-hosted product never enables it (it needs Supabase to be configured).
export interface DemoData {
  analysis: AnalysisResult
  diagnosis: Record<Lang, string>
  /** Pre-generated investigation report (added in 1.3.0; older demo.json lacks it). */
  investigation?: Record<Lang, string>
}

export const DEMO_HASH = '#demo'
export const BUY_URL = 'https://sebaandrada6.gumroad.com/l/hspgx'

/** True while the URL fragment is `#demo`; follows back/forward and link clicks. */
export function useDemoRoute(): boolean {
  const [active, setActive] = useState(() => window.location.hash === DEMO_HASH)
  useEffect(() => {
    const onChange = () => setActive(window.location.hash === DEMO_HASH)
    window.addEventListener('hashchange', onChange)
    return () => window.removeEventListener('hashchange', onChange)
  }, [])
  return active
}

export async function loadDemo(): Promise<DemoData> {
  const response = await fetch('/demo/demo.json')
  if (!response.ok) throw new Error(`Demo not available (${response.status})`)
  return (await response.json()) as DemoData
}
